import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd()

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
[package]
name="{name}"
version="0.1.0"

[[target.bin]]
name="{name}"
path="src/main.fzy"
'''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

match_cleanup = verify('match_cleanup', '''
    fn main() -> i32 {
        let p = alloc(32)
        match true {
            true => free(p),
            _ => 0,
        }
        free(p)
        return 0
    }
''', 1)
match_messages = [item['message'] for item in match_cleanup['items']]
assert any('divergent ownership state for `p`' in message or 'uses conditionally consumed value `p`' in message or 'consumes non-owned or already-consumed value `p`' in message for message in match_messages), match_cleanup

ffi_grouped = verify('ffi_grouped', '''
    ext unsafe c fn take_owned(p_owned: *u8) -> i32;
    unsafe fn main() -> i32 {
        let p = alloc(32)
        discard take_owned((p))
        free(p)
        return 0
    }
''', 1)
assert any('double-frees provenance root' in item['message'] for item in ffi_grouped['items']), ffi_grouped

ffi_projected = verify('ffi_projected', '''
    struct Holder { ptr: *mut u8 }
    ext unsafe c fn take_owned(p_owned: *u8) -> i32;
    unsafe fn main() -> i32 {
        let holder: Holder = Holder { ptr: alloc(32) }
        discard take_owned(holder.ptr)
        free(holder.ptr)
        return 0
    }
''', 1)
assert any('consumes non-owned or already-consumed value `holder`' in item['message'] or 'divergent ownership state for `holder`' in item['message'] or 'double-frees provenance root' in item['message'] for item in ffi_projected['items']), ffi_projected

helper_clean = verify('helper_clean', '''
    fn inspect(p: *mut u8) -> i32 {
        discard p
        return 0
    }
    fn main() -> i32 {
        let p = alloc(32)
        discard inspect(p)
        free(p)
        return 0
    }
''', 0)
assert helper_clean['errors'] == 0, helper_clean

extern_clean = verify('extern_clean', '''
    ext unsafe c fn take_owned(p_owned: *mut u8) -> i32;
    unsafe fn main() -> i32 {
        let p = alloc(32)
        discard take_owned(p)
        return 0
    }
''', 0)
assert extern_clean['errors'] == 0, extern_clean

grouped_return_clean = verify('grouped_return_clean', '''
    fn produce() -> *mut u8 {
        let p = alloc(32)
        return (p)
    }
    fn main() -> i32 {
        let p = produce()
        free(p)
        return 0
    }
''', 0)
assert grouped_return_clean['errors'] == 0, grouped_return_clean
